    let timer: ReturnType<typeof setTimeout> | null = null;
    return (...args: any[]) => {
        if (timer !== null) {
            clearTimeout(timer); // cancel any pending call
        }
        timer = setTimeout(() => {
            fn(args);
            timer = null; // reset timer after execution
        }, waitMs);
    };
}
```

